"""The import page (/importar): a phone backup is merged into the home kept on this computer."""

IMPORT_PAGE = """<!doctype html><html lang="es" data-hoard-app="homehoard"><meta charset="utf-8"><meta name="theme-color" content="#1c1814"><meta name="viewport" content="width=device-width,initial-scale=1"><title>HomeHoard · Importar copia</title>
<link rel="icon" type="image/png" href="/icon.png"><style>:root {color-scheme: dark;--hoard-font-serif: 'Cinzel', 'Iowan Old Style', Charter, Georgia, 'Liberation Serif', 'Noto Serif', 'Times New Roman', serif;--hoard-font-sans: 'Source Sans 3', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Noto Sans', 'Liberation Sans', Arial, sans-serif;--hoard-font-mono: 'JetBrains Mono', ui-monospace, SFMono-Regular, Menlo, Consolas, 'Liberation Mono', monospace;--hoard-radius-sm: 6px;--hoard-radius: 8px;--hoard-radius-lg: 10px;--hoard-sidebar-w: 220px;--hoard-header-h: 64px;--hoard-success: #4a9e6d;--hoard-warning: #d4a843;--hoard-danger: #c4463a;--hoard-info: #4a7ec4;--hoard-shadow: 0 8px 28px rgba(0, 0, 0, 0.38);--hoard-focus: 0 0 0 2px var(--hoard-accent);}html[data-hoard-app="homehoard"] {--hoard-deep: #1c1814;--hoard-sunken: #161310;--hoard-surface: #24201b;--hoard-elevated: #2f2a25;--hoard-hover: #38322b;--hoard-border: #433c35;--hoard-border-hover: #6a6158;--hoard-text: #ece7e1;--hoard-text-muted: #beb9b4;--hoard-text-dim: #a6a19b;--hoard-accent: #e5913f;--hoard-accent-strong: #eaa663;--hoard-accent-dim: #ba732d;--hoard-accent-ink: #1b1713;--hoard-accent-rgb: 229, 145, 63;--hoard-accent-soft: rgba(229, 145, 63, 0.14);--hoard-accent-line: rgba(229, 145, 63, 0.38);}html{background:var(--hoard-deep)}*{box-sizing:border-box}body{margin:0;background:var(--hoard-deep);color:var(--hoard-text);font-family:var(--hoard-font-sans);-webkit-font-smoothing:antialiased}::selection{background:var(--hoard-accent-soft);color:var(--hoard-text)}*{scrollbar-width:thin;scrollbar-color:var(--hoard-border) transparent}header{display:flex;align-items:center;gap:12px;height:var(--hoard-header-h);padding:0 32px;background:var(--hoard-surface);border-bottom:1px solid var(--hoard-border);font-family:var(--hoard-font-serif);font-size:20px;font-weight:700;color:var(--hoard-accent)}header b{display:grid;place-items:center;width:32px;height:32px;border-radius:8px;background:var(--hoard-accent);color:var(--hoard-accent-ink);font-family:var(--hoard-font-sans);font-size:18px}main{padding:0 0 80px}main>:not(header){width:min(690px,100% - 48px);margin-left:auto;margin-right:auto}main>header{margin-bottom:40px}.eyebrow{color:var(--hoard-text-dim);font-size:11px;font-weight:600;text-transform:uppercase;letter-spacing:.08em;margin-top:24px;margin-bottom:10px}h1{font-family:var(--hoard-font-serif);font-weight:700;font-size:30px;letter-spacing:0;line-height:1.15;margin:0 0 12px;color:var(--hoard-text)}p{line-height:1.6;font-size:14px;color:var(--hoard-text-muted)}section{background:var(--hoard-surface);border:1px solid var(--hoard-border);border-radius:var(--hoard-radius-lg);padding:24px;margin-top:28px;margin-bottom:28px}section:hover{border-color:var(--hoard-border-hover)}h2{font-size:15px;font-weight:600;margin:0 0 8px;color:var(--hoard-text)}label{display:block;margin:20px 0 10px;font-size:14px;font-weight:600;color:var(--hoard-text)}input{font:inherit;max-width:100%;color:var(--hoard-text);background:var(--hoard-sunken);border:1px solid var(--hoard-border);border-radius:var(--hoard-radius);padding:8px 10px}input::file-selector-button{font:inherit;color:var(--hoard-text);background:var(--hoard-elevated);border:1px solid var(--hoard-border);border-radius:var(--hoard-radius-sm);padding:4px 10px;margin-right:10px;cursor:pointer}button{font:inherit;font-weight:600;background:var(--hoard-accent);color:var(--hoard-accent-ink);border:0;border-radius:var(--hoard-radius);height:40px;padding:0 20px;cursor:pointer;margin-top:17px}button:hover{background:var(--hoard-accent-strong)}button:focus-visible,input:focus-visible{outline:2px solid var(--hoard-accent);outline-offset:2px}.status{font-size:14px;font-weight:600;color:var(--hoard-accent)}.error{color:var(--hoard-danger)}.foot{font-size:13px;color:var(--hoard-text-dim)}</style><main><header><b>⌂</b> HomeHoard</header><div class="eyebrow">Este ordenador guarda tu casa</div><h1>Importar una copia</h1><p>Carga una copia JSON exportada desde HomeHoard, por ejemplo desde el móvil. Se combina con la casa de este ordenador: para cada habitación, mueble, objeto o tarea gana el cambio más reciente, y una copia sin fotos nunca borra las que ya hay.</p><section><h2>Casa en este ordenador</h2><p id="status" class="status">Comprobando…</p><label for="file">Archivo exportado desde HomeHoard</label><input id="file" type="file" accept=".json,application/json"><br><button id="upload" type="button">Combinar con esta casa</button><p id="message" role="status"></p></section><p class="foot">El archivo se procesa en este ordenador. <a href="/" style="color:var(--hoard-accent)">Abrir HomeHoard</a></p></main>
<script>
const statusEl=document.getElementById('status'),message=document.getElementById('message');
async function refresh(){const r=await fetch('/api/status');const s=await r.json();statusEl.textContent=s.ready?`${s.items} objetos · último cambio ${s.exported_at?new Date(s.exported_at).toLocaleString('es-ES'):'sin fecha'}`:'Todavía no hay objetos en este ordenador';}
document.getElementById('upload').onclick=async()=>{const file=document.getElementById('file').files[0];if(!file){message.textContent='Elige primero una copia JSON.';message.className='error';return;}try{const data=JSON.parse(await file.text());const r=await fetch('/api/import',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const body=await r.json();if(!r.ok)throw Error(body.error||'No se pudo importar');message.textContent=`Copia combinada: ${body.applied} cambios aplicados, ${body.ignored} ya estaban al día.`;message.className='status';await refresh();}catch(e){message.textContent=e.message;message.className='error';}};refresh();
</script></html>"""

